 17 Loan Risk Modeling library(tidyverse) library(reticulate) library(caret) library(MASS) library(rpart) library(rpart.plot) knitr::opts_chunk$set(warning = FALSE, message = FALSE, fig.width = 10, fig.height = 6) theme_set(theme_minimal(base_size = 14)) 17.1 Data Load reticulate::use_python(&quot;C:/Users/casti/AppData/Local/Programs/Python/Python313/python.exe&quot;, required = TRUE) Sys.setenv(RETICULATE_UV_ENABLED = &quot;0&quot;) datasets &lt;- import(&quot;datasets&quot;) ds &lt;- datasets$load_dataset(&quot;supersam7/foot_traffic&quot;) df &lt;- as_tibble(ds[&quot;train&quot;]$to_pandas()) glimpse(df) ## Rows: 11,373 ## Columns: 7 ## $ pedestrians &lt;dbl&gt; 3172, 14, 10, 521, 126, 2628, 1602, 23, 37, 2709, 2271, … ## $ weather &lt;chr&gt; &quot;clear-day&quot;, &quot;partly-cloudy-night&quot;, &quot;partly-cloudy-night… ## $ temperature &lt;dbl&gt; 44, 41, 36, 76, 35, 73, 48, 32, 57, 41, 81, 44, 87, 67, … ## $ precipitation &lt;dbl&gt; 0.0000, 0.0000, 0.0000, 0.0087, 0.0000, 0.0000, 0.0000, … ## $ hour &lt;dbl&gt; 14, 21, 21, 9, 6, 19, 15, 21, 21, 15, 13, 9, 13, 22, 14,… ## $ weekday &lt;chr&gt; &quot;Wednesday&quot;, &quot;Sunday&quot;, &quot;Thursday&quot;, &quot;Tuesday&quot;, &quot;Monday&quot;, … ## $ temp_forecast &lt;dbl&gt; 37.11765, 41.17647, 40.17647, 75.76471, 50.05882, 70.764… 17.2 Task 1: Explore Variables # Numeric variables density df %&gt;% select_if(is.numeric) %&gt;% pivot_longer(everything()) %&gt;% ggplot(aes(value)) + geom_density(fill = &quot;#007bff&quot;, alpha = 0.7) + facet_wrap(~name, scales = &quot;free&quot;) + labs(title = &quot;Density of Numeric Variables&quot;) # Categorical variables df %&gt;% select_if(is.character) %&gt;% pivot_longer(everything()) %&gt;% ggplot(aes(value)) + geom_bar(fill = &quot;#007bff&quot;) + facet_wrap(~name, scales = &quot;free_x&quot;) + coord_flip() + labs(title = &quot;Distribution of Categorical Variables&quot;) # Pedestrians vs key factors ggplot(df, aes(weekday, pedestrians)) + geom_boxplot(fill = &quot;#007bff&quot;) + coord_flip() ggplot(df, aes(weather, pedestrians)) + geom_boxplot(fill = &quot;#007bff&quot;) + coord_flip() ggplot(df, aes(temperature, pedestrians)) + geom_point(alpha = 0.3, color = &quot;#007bff&quot;) + geom_smooth() 17.3 Task 2: Reduce Factor Levels # Weekday: Weekend vs Weekday df$weekday &lt;- fct_collapse(df$weekday, Weekend = c(&quot;Saturday&quot;, &quot;Sunday&quot;), Weekday = c(&quot;Monday&quot;, &quot;Tuesday&quot;, &quot;Wednesday&quot;, &quot;Thursday&quot;, &quot;Friday&quot;)) # Weather: simplified df$weather &lt;- fct_collapse(df$weather, &quot;Nice&quot; = c(&quot;clear-day&quot;, &quot;partly-cloudy-day&quot;, &quot;clear-night&quot;, &quot;partly-cloudy-night&quot;), &quot;Rain&quot; = &quot;rain&quot;, &quot;Bad&quot; = c(&quot;fog&quot;, &quot;sleet&quot;, &quot;snow&quot;, &quot;wind&quot;, &quot;cloudy&quot;)) table(df$weekday) ## ## Weekday Weekend ## 8126 3247 table(df$weather) ## ## Nice Bad Rain ## 8942 1752 679 17.4 Task 3: Modify Hour &amp; Temperature # Hour from peak (2pm = 14) df$hour_dist &lt;- abs(df$hour - 14) # Use forecast temperature (smoother relationship) df$temp_use &lt;- df$temp_forecast # Clean up # Clean up df &lt;- df %&gt;% dplyr::select(-hour, -temperature, -temp_forecast) 17.5 Task 4: Target Transformation # sqrt(pedestrians) often stabilizes variance ggplot(df, aes(sqrt(pedestrians))) + geom_histogram(fill = &quot;#007bff&quot;, bins = 40) df$ped_sqrt &lt;- sqrt(df$pedestrians) 17.6 Task 5: Trees (Original &amp; Transformed) set.seed(123) split &lt;- createDataPartition(df$pedestrians, p = 0.8, list = FALSE) train &lt;- df[split, ] test &lt;- df[-split, ] # Tree 1: raw pedestrians tree1 &lt;- rpart(pedestrians ~ . - ped_sqrt, data = train, control = rpart.control(minbucket = 50, cp = 0.0001, maxdepth = 5)) rpart.plot(tree1, main = &quot;Tree on Raw Pedestrians&quot;) # Tree 2: sqrt transformed tree2 &lt;- rpart(ped_sqrt ~ . - pedestrians, data = train, control = rpart.control(minbucket = 50, cp = 0.0001, maxdepth = 5)) rpart.plot(tree2, main = &quot;Tree on sqrt(Pedestrians)&quot;) # RMSE comparison rmse &lt;- function(actual, pred) sqrt(mean((actual - pred)^2)) pred1 &lt;- predict(tree1, test) pred2 &lt;- predict(tree2, test)^2 # back-transform cat(&quot;Raw Tree Test RMSE:&quot;, rmse(test$pedestrians, pred1), &quot;
&quot;) ## Raw Tree Test RMSE: 435.111 cat(&quot;Sqrt Tree Test RMSE:&quot;, rmse(test$pedestrians, pred2), &quot;
&quot;) ## Sqrt Tree Test RMSE: 450.3347 17.7 Task 7: GLM (Poisson &amp; Gamma) glm_pois &lt;- glm(pedestrians ~ . - ped_sqrt, family = poisson(link = &quot;log&quot;), data = train) glm_gamma &lt;- glm(pedestrians ~ . - ped_sqrt, family = Gamma(link = &quot;log&quot;), data = train) rmse_pois &lt;- rmse(test$pedestrians, predict(glm_pois, test, type = &quot;response&quot;)) rmse_gamma &lt;- rmse(test$pedestrians, predict(glm_gamma, test, type = &quot;response&quot;)) cat(&quot;Poisson GLM Test RMSE:&quot;, rmse_pois, &quot;
&quot;) ## Poisson GLM Test RMSE: 550.9564 cat(&quot;Gamma GLM Test RMSE:&quot;, rmse_gamma, &quot;
&quot;) ## Gamma GLM Test RMSE: 953.4377 17.8 Task 8: Interaction (hour_dist * weather) glm_int &lt;- glm(pedestrians ~ . - ped_sqrt + hour_dist * weather, family = poisson(link = &quot;log&quot;), data = train) summary(glm_int) ## ## Call: ## glm(formula = pedestrians ~ . - ped_sqrt + hour_dist * weather, ## family = poisson(link = &quot;log&quot;), data = train) ## ## Coefficients: ## Estimate Std. Error z value Pr(&gt;|z|) ## (Intercept) 6.990e+00 1.325e-03 5276.53 &lt;2e-16 *** ## weatherBad -1.445e-01 1.616e-03 -89.43 &lt;2e-16 *** ## weatherRain -6.015e-01 4.120e-03 -145.99 &lt;2e-16 *** ## precipitation -6.875e+00 4.633e-02 -148.39 &lt;2e-16 *** ## weekdayWeekend 2.954e-01 7.094e-04 416.45 &lt;2e-16 *** ## hour_dist -2.877e-01 1.685e-04 -1707.14 &lt;2e-16 *** ## temp_use 1.467e-02 1.949e-05 752.64 &lt;2e-16 *** ## weatherBad:hour_dist -3.375e-02 4.898e-04 -68.90 &lt;2e-16 *** ## weatherRain:hour_dist -2.293e-02 1.056e-03 -21.71 &lt;2e-16 *** ## --- ## Signif. codes: 0 &#39;***&#39; 0.001 &#39;**&#39; 0.01 &#39;*&#39; 0.05 &#39;.&#39; 0.1 &#39; &#39; 1 ## ## (Dispersion parameter for poisson family taken to be 1) ## ## Null deviance: 7827274 on 9100 degrees of freedom ## Residual deviance: 2617719 on 9092 degrees of freedom ## AIC: 2689817 ## ## Number of Fisher Scoring iterations: 5 rmse_int &lt;- rmse(test$pedestrians, predict(glm_int, test, type = &quot;response&quot;)) cat(&quot;GLM with Interaction Test RMSE:&quot;, rmse_int, &quot;
&quot;) ## GLM with Interaction Test RMSE: 549.4676 17.9 Task 9: Feature Selection (BIC backward) glm_full &lt;- glm(pedestrians ~ . - ped_sqrt + hour_dist * weather, family = poisson(link = &quot;log&quot;), data = train) glm_bic &lt;- stepAIC(glm_full, direction = &quot;backward&quot;, k = log(nrow(train))) ## Start: AIC=2689881 ## pedestrians ~ (weather + precipitation + weekday + hour_dist + ## temp_use + ped_sqrt) - ped_sqrt + hour_dist * weather ## ## Df Deviance AIC ## &lt;none&gt; 2617719 2689881 ## - weather:hour_dist 2 2622864 2695008 ## - precipitation 1 2647396 2719549 ## - weekday 1 2785610 2857762 ## - temp_use 1 3202377 3274529 summary(glm_bic) ## ## Call: ## glm(formula = pedestrians ~ (weather + precipitation + weekday + ## hour_dist + temp_use + ped_sqrt) - ped_sqrt + hour_dist * ## weather, family = poisson(link = &quot;log&quot;), data = train) ## ## Coefficients: ## Estimate Std. Error z value Pr(&gt;|z|) ## (Intercept) 6.990e+00 1.325e-03 5276.53 &lt;2e-16 *** ## weatherBad -1.445e-01 1.616e-03 -89.43 &lt;2e-16 *** ## weatherRain -6.015e-01 4.120e-03 -145.99 &lt;2e-16 *** ## precipitation -6.875e+00 4.633e-02 -148.39 &lt;2e-16 *** ## weekdayWeekend 2.954e-01 7.094e-04 416.45 &lt;2e-16 *** ## hour_dist -2.877e-01 1.685e-04 -1707.14 &lt;2e-16 *** ## temp_use 1.467e-02 1.949e-05 752.64 &lt;2e-16 *** ## weatherBad:hour_dist -3.375e-02 4.898e-04 -68.90 &lt;2e-16 *** ## weatherRain:hour_dist -2.293e-02 1.056e-03 -21.71 &lt;2e-16 *** ## --- ## Signif. codes: 0 &#39;***&#39; 0.001 &#39;**&#39; 0.01 &#39;*&#39; 0.05 &#39;.&#39; 0.1 &#39; &#39; 1 ## ## (Dispersion parameter for poisson family taken to be 1) ## ## Null deviance: 7827274 on 9100 degrees of freedom ## Residual deviance: 2617719 on 9092 degrees of freedom ## AIC: 2689817 ## ## Number of Fisher Scoring iterations: 5 17.10 Task 10-11: Final Model &amp; Validation # Retrain final selected model on full training data final_glm &lt;- glm(formula(glm_bic), family = poisson(link = &quot;log&quot;), data = train) # Final test RMSE final_pred &lt;- predict(final_glm, test, type = &quot;response&quot;) final_rmse &lt;- rmse(test$pedestrians, final_pred) cat(&quot;Final Model Test RMSE:&quot;, final_rmse, &quot;
